/**
 * Loading indicator for work of unknown duration (`design/components/spinner.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/spinner.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { Component, ViewEncapsulation, input } from '@angular/core'

import { Icon, MEMBER_PROVIDERS, useMember, type IconProps } from '@polymorph/angular'
import styles from '@polymorph/recipes/structure/spinner.module.css'

/** Loading indicator for work of unknown duration: the inputs it takes, by the React member's prop names. */
export interface SpinnerProps {
  /**
   * Announced once, so screen reader users know something is loading.
   */
  label?: string
  size?: 'sm' | 'md' | 'lg'
}

/** Loading indicator for work of unknown duration. */
@Component({
  selector: 'pm-spinner',
  encapsulation: ViewEncapsulation.None,
  host: { style: 'display: contents' },
  providers: [...MEMBER_PROVIDERS],
  imports: [Icon],
  // prettier-ignore
  template: `<span
[attr.class]="e1()"
[attr.data-size]="e2()"
role="status"
data-member="spinner"
><!-- glyph -->
<span
[attr.class]="e3()"
><pm-icon
name="loading"
[size]="e4()"
></pm-icon></span>
<!-- label -->
<span
[attr.class]="e5()"
>{{ e6() }}</span></span>`,
})
export class Spinner {
  /**
   * Announced once, so screen reader users know something is loading.
   */
  readonly label = input<Exclude<SpinnerProps['label'], undefined>, SpinnerProps['label']>(
    'Loading',
    { transform: (value: SpinnerProps['label']) => (value === undefined ? 'Loading' : value) },
  )
  readonly size = input<Exclude<SpinnerProps['size'], undefined>, SpinnerProps['size']>('md', {
    transform: (value: SpinnerProps['size']) => (value === undefined ? 'md' : value),
  })
  protected readonly $ = useMember({
    events: [],
    props: { label: () => this.label(), size: () => this.size() },
  })
  protected readonly $p = this.$.props

  protected e1() {
    return styles.spinner
  }

  protected e2() {
    return this.$p.size
  }

  protected e3() {
    return styles.glyph
  }

  protected e4(): IconProps['size'] {
    return this.$p.size
  }

  protected e5() {
    return styles.label
  }

  protected e6() {
    return this.$p.label
  }
}
